105	/// Validate and tokenize borrowed source before touching the destination, then
106	/// atomically replace an existing regular file or publish a missing file.
107	/// `token_capacity` bounds the owned token vector and source/path remain borrowed.
108	pub fn source_save_noop<'source>(
109	    source: &'source [u8],
110	    path: &[u8],
111	    token_capacity: usize,
112	    mut hooks: Option<&mut dyn SourceSaveHooks>,
113	) -> SourceSaveResult<'source> {
114	    if path.is_empty() {
115	        return SourceSaveResult::error(SourceSaveError::Invalid, XmlDiagnostic::default());
116	    }
117	    if path.len() > MAX_ATOMIC_FILE_PATH_BYTES {
118	        return SourceSaveResult::error(SourceSaveError::PathLimit, XmlDiagnostic::default());
119	    }
120	    if source.len() > MAX_INPUT_BYTES {
121	        return SourceSaveResult::error(
122	            SourceSaveError::InputLimit,
123	            XmlDiagnostic { category: XmlError::InputLimit, offset: MAX_INPUT_BYTES },
124	        );
125	    }
126	
127	    let (tokens, parsed) = tokenize_with_capacity(source, XmlLimits::default(), token_capacity);
128	    if parsed.diagnostic.category != XmlError::None {
129	        return SourceSaveResult::error(SourceSaveError::Tokenizer, parsed.diagnostic);
130	    }
131	
132	    let replaced = match hooks.as_deref_mut() {
133	        Some(hook) => atomic_file_replace(path, source, Some(&mut ReplaceAdapter(hook))),
134	        None => atomic_file_replace(path, source, None),
135	    };
136	    let file_result = if replaced.error == AtomicFileReplaceError::NotFound {
137	        let created = match hooks.as_deref_mut() {
138	            Some(hook) => atomic_file_create_new(path, source, Some(&mut CreateAdapter(hook))),
139	            None => atomic_file_create_new(path, source, None),
140	        };
141	        map_create_result(created)
142	    } else {
143	        replaced
144	    };
145	    let error = match file_result.error {
146	        AtomicFileReplaceError::Ok => SourceSaveError::Ok,
147	        AtomicFileReplaceError::Durability => SourceSaveError::Durability,
148	        _ => SourceSaveError::Destination,
149	    };
150	    SourceSaveResult {
151	        error,
152	        parse_diagnostic: parsed.diagnostic,
153	        tokens,
154	        file_result,
155	        _source: PhantomData,
156	    }
157	}
158	
159	fn map_create_result(created: AtomicFileCreateNewResult) -> AtomicFileReplaceResult {
160	    AtomicFileReplaceResult {
161	        error: match created.error {
162	            AtomicFileCreateNewError::Ok => AtomicFileReplaceError::Ok,
163	            AtomicFileCreateNewError::Durability => AtomicFileReplaceError::Durability,
164	            _ => AtomicFileReplaceError::Io,
165	        },
166	        file_synced: created.file_synced,
167	        renamed: created.published,
168	        directory_synced: created.directory_synced,
169	    }
170	}
